    return E / np.linalg.norm(E, axis=1, keepdims=True)

def retrieve(q, E, embed, k=4):
    v = np.asarray(embed(q), float)
    s = E @ (v / np.linalg.norm(v))
    top = np.argsort(-s)[:k]
